17: @RestController
18: @RequestMapping("/revenue")
19: @Validated
20: public class RevenueController {
21:     private static final Logger log = LoggerFactory.getLogger(RevenueController.class);
22:
23:     private final IRevenueService revenueService;
24:
25:     public RevenueController(IRevenueService revenueService) {
26:         this.revenueService = revenueService;
27:     }
28:
29:     // Synchronous recognition (default). Returns 201 Created with Location header.
30:     @PostMapping("/recognize")
31:     public ResponseEntity<RecognizeResponse> recognize(@Valid @RequestBody RecognizeRequest request,
32:                                                        @RequestHeader(value = "Idempotency-Key", required = false) String idempotencyKey) {
33:         log.debug("POST /revenue/recognize called for contractId={}", request.getContractId());
34:
35:         RecognizeResponse resp = revenueService.recognizeRevenue(request, idempotencyKey);
36:
37:         HttpHeaders headers = new HttpHeaders();
38:         if (resp.getResourceLocation() != null) {
39:             headers.add(HttpHeaders.LOCATION, resp.getResourceLocation());
40:             return new ResponseEntity<>(resp, headers, HttpStatus.CREATED);
41:         }
42:         // If service decided to enqueue for async processing
43:         return new ResponseEntity<>(resp, HttpStatus.ACCEPTED);
44:     }
45:
46:     @GetMapping("/{id}")
47:     public ResponseEntity<RevenueDto> getRevenue(@PathVariable("id") String id) {
48:         log.debug("GET /revenue/{}", id);
49:         RevenueDto dto = revenueService.getRevenueById(id);
50:         if (dto == null) {
51:             return ResponseEntity.notFound().build();
52:         }
53:         return ResponseEntity.ok(dto);
54:     }
55: }

