7: import com.example.revenue.model.Money;
8: import com.example.revenue.persistence.RevenueEntity;
9: import com.example.revenue.persistence.RevenueRepository;
10: import com.example.revenue.service.IRevenueService;
11: import org.slf4j.Logger;
12: import org.slf4j.LoggerFactory;
13: import org.springframework.stereotype.Service;
14: import org.springframework.transaction.annotation.Transactional;
15:
16: import java.time.OffsetDateTime;
17: import java.util.Optional;
18: import java.util.UUID;
19:
20: @Service
21: public class RevenueServiceImpl implements IRevenueService {
22:     private static final Logger log = LoggerFactory.getLogger(RevenueServiceImpl.class);
23:
24:     private final RevenueRepository revenueRepository;
25:     private final IRevenueCalculator calculator;
26:     private final IdempotencyRecordService idempotencyService; // small helper (not pasted yet)
27:
28:     public RevenueServiceImpl(RevenueRepository revenueRepository,
29:                               IRevenueCalculator calculator,
30:                               IdempotencyRecordService idempotencyService) {
31:         this.revenueRepository = revenueRepository;
32:         this.calculator = calculator;
33:         this.idempotencyService = idempotencyService;
34:     }
35:
36:     @Override
37:     @Transactional
38:     public RecognizeResponse recognizeRevenue(RecognizeRequest request, String idempotencyKey) {
39:         // Basic idempotency handling: if key present and record exists, return stored response
40:         if (idempotencyKey != null) {
41:             RecognizeResponse existing = idempotencyService.getResponseForKey(idempotencyKey);
42:             if (existing != null) {
43:                 log.debug("Idempotent hit for key={}", idempotencyKey);
44:                 return existing;
45:             }
46:         }
47:
48:         // Validate domain-level invariants (additional to controller validation)
49:         if (request.getAmount().compareTo(Money.ZERO) < 0) {
50:             throw new IllegalArgumentException("amount must be >= 0");
51:         }
52:
53:         // Compute recognition schedule (may be synchronous and cheap or heavy — simplified here)
54:         // Use calculator to determine recognized amounts/dates
55:         var schedule = calculator.calculateRecognitionSchedule(request.getContractId(), request.getAmount(), request.getStartDate(), request.getEndDate());
56:
57:         // Persist recognized revenue aggregate entity
58:         RevenueEntity entity = new RevenueEntity();
59:         entity.setId(UUID.randomUUID().toString());
60:         entity.setContractId(request.getContractId());
61:         entity.setTotalAmount(request.getAmount());
62:         entity.setCurrency(request.getCurrency());
63:         entity.setCreatedAt(OffsetDateTime.now());
64:         entity.setRecognitionSchedule(schedule.toPersistable());
65:
66:         // Save — optimistic locking annotations on entity prevent double-write on concurrent updates
67:         RevenueEntity saved = revenueRepository.save(entity);
68:
69:         // Build response with Location header pointing to GET /revenue/{id}
70:         RecognizeResponse resp = RecognizeResponse.builder()
71:                 .resourceLocation("/revenue/" + saved.getId())
72:                 .revenueId(saved.getId())
73:                 .createdAt(saved.getCreatedAt())
74:                 .build();
75:
76:         // Store idempotency mapping if key provided
77:         if (idempotencyKey != null) {
78:             idempotencyService.storeResponseForKey(idempotencyKey, resp);
79:         }
80:
81:         log.info("Recognized revenue id={} for contract={}", saved.getId(), saved.getContractId());
82:         return resp;
83:     }
84:
85:     @Override
86:     @Transactional(readOnly = true)
87:     public RevenueDto getRevenueById(String revenueId) {
88:         Optional<RevenueEntity> e = revenueRepository.findById(revenueId);
89:         if (e.isEmpty()) return null;
90:         RevenueEntity ent = e.get();
91:
92:         // Map entity to DTO (mapping utility omitted for brevity)
93:         RevenueDto dto = RevenueDto.builder()
94:                 .id(ent.getId())
95:                 .contractId(ent.getContractId())
96:                 .totalAmount(ent.getTotalAmount())
97:                 .currency(ent.getCurrency())
98:                 .recognitionSchedule(ent.getRecognitionSchedule())
99:                 .createdAt(ent.getCreatedAt())
100:                 .build();
101:
102:         return dto;
103:     }
104: }

