1: package com.example.revenue.service.impl;
2:
3: import com.example.revenue.api.dto.RecognizeResponse;
4: import com.example.revenue.persistence.IdempotencyRecord;
5: import com.example.revenue.persistence.IdempotencyRecordRepository;
6: import org.slf4j.Logger;
7: import org.slf4j.LoggerFactory;
8: import org.springframework.dao.DataIntegrityViolationException;
9: import org.springframework.stereotype.Service;
10: import org.springframework.transaction.annotation.Transactional;
11:
12: import java.util.Optional;
13:
14: @Service
15: public class IdempotencyRecordService {
16:     private static final Logger log = LoggerFactory.getLogger(IdempotencyRecordService.class);
17:
18:     private final IdempotencyRecordRepository repo;
19:
20:     public IdempotencyRecordService(IdempotencyRecordRepository repo) {
21:         this.repo = repo;
22:     }
23:
24:     /**
25:      * Returns previously stored response for key, or null when not present.
26:      * Note: callers should trim/validate the key before calling.
27:      */
28:     @Transactional(readOnly = true)
29:     public RecognizeResponse getResponseForKey(String key) {
30:         if (key == null || key.trim().isEmpty()) return null;
31:         Optional<IdempotencyRecord> r = repo.findByKey(key.trim());
32:         if (r.isEmpty()) return null;
33:         IdempotencyRecord rec = r.get();
34:         // storedResponse is JSON; deserialize to RecognizeResponse (simple mapper presumed)
35:         return rec.toRecognizeResponse();
36:     }
37:
38:     /**
39:      * Attempts to store the response for a key. If another process inserts the same key concurrently,
40:      * a DataIntegrityViolationException will be thrown by the DB unique constraint. In that case,
41:      * we return the existing stored response to the caller to preserve idempotency semantics.
42:      */
43:     @Transactional
44:     public RecognizeResponse storeResponseForKey(String key, RecognizeResponse resp) {
45:         if (key == null || key.trim().isEmpty()) {
46:             throw new IllegalArgumentException("idempotency key must be provided when storing");
47:         }
48:         String k = key.trim();
49:         IdempotencyRecord rec = new IdempotencyRecord();
50:         rec.setIdempotencyKey(k);
51:         rec.setResponseJson(IdempotencyRecord.serialize(resp));
52:         try {
53:             repo.save(rec);
54:             return resp;
55:         } catch (DataIntegrityViolationException ex) {
56:             log.debug("Idempotency insert conflict for key={}, returning existing response", k);
57:             // Another process inserted — return the existing stored response
58:             Optional<IdempotencyRecord> existing = repo.findByKey(k);
59:             return existing.map(IdempotencyRecord::toRecognizeResponse).orElseThrow(() -> ex);
60:         }
61:     }
62: }

