+@Service
+public class IdempotencyRecordService {
+    private static final Logger log = LoggerFactory.getLogger(IdempotencyRecordService.class);
+
+    private final IdempotencyRecordRepository repo;
+
+    public IdempotencyRecordService(IdempotencyRecordRepository repo) {
+        this.repo = repo;
+    }
+
+    /**
+     * Try to atomically create an IN_PROGRESS idempotency record using a new transaction.
+     * Returns true if this caller acquired the key (insert succeeded); false if a record already exists.
+     */
+    @Transactional(propagation = Propagation.REQUIRES_NEW)
+    public boolean tryAcquire(String key) {
+        if (key == null || key.trim().isEmpty()) throw new IllegalArgumentException("idempotency key required");
+        String k = key.trim();
+        IdempotencyRecord rec = new IdempotencyRecord();
+        rec.setIdempotencyKey(k);
+        rec.setState(IdempotencyRecord.State.IN_PROGRESS);
+        try {
+            repo.save(rec);
+            return true;
+        } catch (DataIntegrityViolationException ex) {
+            log.debug("tryAcquire: key already exists={}", k);
+            return false;
+        }
+    }
+
+    /**
+     * Mark an existing idempotency record as COMPLETED and store minimal response fields.
+     */
+    @Transactional
+    public void markCompleted(String key, RecognizeResponse resp) {
+        String k = key.trim();
+        Optional<IdempotencyRecord> r = repo.findByKey(k);
+        if (r.isEmpty()) throw new IllegalStateException("Idempotency record not present to mark completed");
+        IdempotencyRecord rec = r.get();
+        rec.setState(IdempotencyRecord.State.COMPLETED);
+        rec.setRevenueId(resp.getRevenueId());
+        rec.setResourceLocation(resp.getResourceLocation());
+        rec.setCompletedAt(resp.getCreatedAt());
+        rec.setJobId(resp.getJobId());
+        repo.save(rec);
+    }
+
+    /**
+     * Returns completed RecognizeResponse for key, or null if not completed/not present.
+     */
+    @Transactional(readOnly = true)
+    public RecognizeResponse getCompletedResponse(String key) {
+        if (key == null || key.trim().isEmpty()) return null;
+        Optional<IdempotencyRecord> r = repo.findByKey(key.trim());
+        if (r.isEmpty()) return null;
+        return r.get().toRecognizeResponse();
+    }
+
