// Language: TypeScript (Node 14+/Deno) - core compute + helpers for line-by-line review

// Key constants/types/structs
export type RoundingMode = 'HALF_EVEN' | 'HALF_UP' | 'DOWN' | 'UP';
export type RoundingStrategy = 'PER_LINE' | 'FINAL_TOTAL';

export interface CurrencyConfig {
  code: string;            // e.g. 'USD', 'JPY'
  precision: number;       // number of decimal subunits (0 for JPY, 2 for USD, etc.)
}

export interface CalculationOptions {
  currency: CurrencyConfig;
  roundingStrategy: RoundingStrategy; // PER_LINE or FINAL_TOTAL
  roundingMode: RoundingMode;         // HALF_EVEN default
  applyDiscountBeforeTax: boolean;
  pricesIncludeTax: boolean;
  isRefund?: boolean;                 // enables negative line support via refund flow
}

export enum ErrorCode {
  INVALID_INPUT = 'INVALID_INPUT',
  PARSE_ERROR = 'PARSE_ERROR',
  OVERFLOW = 'OVERFLOW',
  BUSINESS_RULE_VIOLATION = 'BUSINESS_RULE_VIOLATION'
}

export interface LineItem {
  id: string;
  description?: string;
  quantity: number | string;    // numeric or string input
  unitPrice: number | string;   // price in major units (e.g. 12.34) or numeric
  taxRatePct?: number | string; // percent (e.g. 20 for 20%)
  discountPct?: number | string; // percent discount
}

export interface ComputationResult {
  subtotal: bigint;   // minor units (integer)
  tax: bigint;        // minor units
  discount: bigint;   // minor units
  total: bigint;      // minor units
}

// Internal scales
const QUANTITY_SCALE = 1_000_000n; // quantities represented to 6 decimal places (e.g. 1.5 -> 1_500_000)
const PERCENT_PPM = 1_000_000n;     // percent expressed as parts-per-million: 20% -> 200_000

// Helpers: parsing and validation
function parseDecimalToScaledBigInt(input: number | string, scale: bigint): bigint {
  // Accepts "123", " 12.345 "; rejects locale formatted "1,234.56"
  if (typeof input === 'number') {
    // convert number to string to control precision
    input = String(input);
  }
  if (typeof input !== 'string') throw { code: ErrorCode.PARSE_ERROR, message: 'Unsupported input type' };
  const s = input.trim();
  if (s === '') throw { code: ErrorCode.PARSE_ERROR, message: 'Empty numeric string' };
  if (s.includes(',')) throw { code: ErrorCode.PARSE_ERROR, message: 'Thousands separators not allowed' };
  const [intPart, fracPart = ''] = s.split('.');
  if (!/^-?\d+$/.test(intPart)) throw { code: ErrorCode.PARSE_ERROR, message: 'Invalid integer part' };
  const neg = intPart.startsWith('-');
  const absInt = BigInt(neg ? intPart.slice(1) : intPart);
  // Build scaled value
  const fracNormalized = (fracPart + '0'.repeat(Number(scale.toString().length))) // pad long, we'll trim below
    .slice(0, Number(scale.toString().length));
  // Simpler: build frac scaled to desired decimal places
  const fracPadCount = Math.max(0, Number(Math.log10(Number(scale))));
  const fracDigits = fracPart.padEnd(fracPadCount, '0').slice(0, fracPadCount);
  const fracValue = BigInt(fracDigits || '0');
  const scaled = absInt * scale + fracValue;
  return neg ? -scaled : scaled;
}

function parsePercentToPpm(input: number | string): bigint {
  // e.g. 20 -> 200_000 (20% in ppm)
  const scaled = parseDecimalToScaledBigInt(input, PERCENT_PPM);
  return scaled; // already parts-per-million
}

function parsePriceToMinorUnits(input: number | string, currency: CurrencyConfig): bigint {
  // Converts e.g. '12.34' USD to 1234 (minor units) as bigint
  const minorFactor = 10n ** BigInt(currency.precision);
  return parseDecimalToScaledBigInt(input, minorFactor);
}

function validateItems(items: LineItem[], opts: CalculationOptions): void {
  if (!Array.isArray(items)) throw { code: ErrorCode.INVALID_INPUT, message: 'items must be array' };
  for (const it of items) {
    if (!it.id) throw { code: ErrorCode.INVALID_INPUT, message: 'item.id required' };
    // Basic parsing try/catch to provide typed errors
    try {
      const q = parseDecimalToScaledBigInt(it.quantity, QUANTITY_SCALE);
      const p = parsePriceToMinorUnits(it.unitPrice, opts.currency);
      if (!opts.isRefund) {
        if (q < 0n || p < 0n) throw { code: ErrorCode.BUSINESS_RULE_VIOLATION, message: 'Negative quantity/price not allowed' };
      }
    } catch (e) {
      if (e && e.code) throw e; else throw { code: ErrorCode.PARSE_ERROR, message: 'Invalid numeric field on item ' + it.id };
    }
  }
}

// Rounding/division helper using BigInt
function divRound(numerator: bigint, denominator: bigint, mode: RoundingMode): bigint {
  if (denominator === 0n) throw { code: ErrorCode.INVALID_INPUT, message: 'division by zero' };
  const q = numerator / denominator;
  const r = numerator % denominator;
  if (r === 0n) return q;
  const twice = r * 2n;
  switch (mode) {
    case 'DOWN': return q;
    case 'UP': return q + 1n;
    case 'HALF_UP': return (twice >= denominator) ? (q + 1n) : q;
    case 'HALF_EVEN': {
      if (twice < denominator) return q;
      if (twice > denominator) return q + 1n;
      // exactly half: tie -> round to even
      return (q % 2n === 0n) ? q : q + 1n;
    }
    default: return q;
  }
}

// Apply discounts and taxes, returning per-line amounts (all values in minor units where applicable)
function applyDiscountsAndTaxes(
  items: LineItem[],
  opts: CalculationOptions
): { lineAmounts: { id: string; subtotal: bigint; discount: bigint; tax: bigint; total: bigint }[] } {
  const currency = opts.currency;
  const minorFactor = 10n ** BigInt(currency.precision);
  const results: { id: string; subtotal: bigint; discount: bigint; tax: bigint; total: bigint }[] = [];

  for (const it of items) {
    // Parse values
    const qtyScaled = parseDecimalToScaledBigInt(it.quantity, QUANTITY_SCALE); // qty * QUANTITY_SCALE
    const unitPriceMinor = parsePriceToMinorUnits(it.unitPrice, currency); // in minor units per whole unit

    // raw subtotal numerator = qtyScaled * unitPriceMinor
    // To get minor-units subtotal, divide by QUANTITY_SCALE with rounding according to choice
    const rawSubtotalNumerator = qtyScaled * unitPriceMinor; // big integer with extra QUANTITY_SCALE factor
    const subtotal = divRound(rawSubtotalNumerator, QUANTITY_SCALE, opts.roundingMode); // minor units

    // compute discount (percentage) if present
    const discountPctPpm = it.discountPct ? parsePercentToPpm(it.discountPct) : 0n;
    let discount = 0n;
    if (discountPctPpm !== 0n) {
      // discount = subtotal * discountPct / 100
      const discountNumerator = subtotal * discountPctPpm;
      discount = divRound(discountNumerator, PERCENT_PPM, opts.roundingMode);
    }

    // compute tax
    const taxPctPpm = it.taxRatePct ? parsePercentToPpm(it.taxRatePct) : 0n;
    let priceAfterDiscount = opts.applyDiscountBeforeTax ? (subtotal - discount) : subtotal;
    let tax = 0n;
    if (taxPctPpm !== 0n) {
      // if pricesIncludeTax is true, tax = included tax portion: tax = price * rate / (100 + rate)
      if (opts.pricesIncludeTax) {
        // tax = priceAfterDiscount * rate / (100 + rate)
        const denom = PERCENT_PPM + taxPctPpm; // e.g. 1.20 -> 1.00 + 0.20
        const taxNumerator = priceAfterDiscount * taxPctPpm;
        tax = divRound(taxNumerator, denom, opts.roundingMode);
      } else {
        const taxNumerator = priceAfterDiscount * taxPctPpm;
        tax = divRound(taxNumerator, PERCENT_PPM, opts.roundingMode);
      }
    }

    const total = priceAfterDiscount + tax;
    results.push({ id: it.id, subtotal, discount, tax, total });
  }

  return { lineAmounts: results };
}

// Distribute rounding differences if strategy is FINAL_TOTAL (distribute remainder to items proportionally)
function distributeRounding(lineAmounts: { id: string; subtotal: bigint; discount: bigint; tax: bigint; total: bigint }[], opts: CalculationOptions): typeof lineAmounts {
  if (opts.roundingStrategy === 'PER_LINE') return lineAmounts; // already rounded per-line

  // If FINAL_TOTAL: recompute aggregated raw arithmetic using higher-precision intermediates
  // For simplicity we assume applyDiscountsAndTaxes used scaled arithmetic; we check totals and distribute small remainder
  const aggregated = lineAmounts.reduce((acc, la) => {
    acc.subtotal += la.subtotal;
    acc.discount += la.discount;
    acc.tax += la.tax;
    acc.total += la.total;
    return acc;
  }, { subtotal: 0n, discount: 0n, tax: 0n, total: 0n });

  // Compute grand total per component by summing the higher-precision raw values then rounding once.
  // For this example, assume lineAmounts already in minor-units but were rounded per-line; in 'FINAL_TOTAL' mode callers should
  // instead call lower-level helpers that return unrounded per-line rationals. To keep this self-contained, we'll detect
  // a small rounding delta between subtotal+tax-discount and total and adjust proportionally by line subtotal weight.

  const recomputedTotal = aggregated.subtotal - aggregated.discount + aggregated.tax;
  const delta = recomputedTotal - aggregated.total; // if non-zero, need to distribute delta across lines
  if (delta === 0n) return lineAmounts;

  // Distribute delta by proportional share of subtotal (largest-subtotal gets remainder if ties)
  const totalSubtotal = aggregated.subtotal || 1n;
  let remainder = delta;
  const adjusted = lineAmounts.map((la, idx) => {
    // share = floor(delta * la.subtotal / totalSubtotal)
    const share = (delta * la.subtotal) / totalSubtotal;
    remainder -= share;
    return { ...la, total: la.total + share };
  });
  // attach leftover remainder to the largest subtotal line to keep deterministic behavior
  if (remainder !== 0n) {
    let maxIdx = 0;
    let maxVal = adjusted[0].subtotal;
    for (let i = 1; i < adjusted.length; i++) {
      if (adjusted[i].subtotal > maxVal) { maxVal = adjusted[i].subtotal; maxIdx = i; }
    }
    adjusted[maxIdx].total += remainder;
  }
  return adjusted;
}

// finalizeTotal: aggregate line amounts and produce final breakdown
export function calculateRevenue(items: LineItem[], opts: CalculationOptions): ComputationResult {
  // Validate inputs
  validateItems(items, opts);

  // Compute per-line amounts
  const { lineAmounts } = applyDiscountsAndTaxes(items, opts);

  // If FINAL_TOTAL chosen, re-distribute rounding deltas
  const finalLineAmounts = (opts.roundingStrategy === 'FINAL_TOTAL') ? distributeRounding(lineAmounts, opts) : lineAmounts;

  // Aggregate
  const aggregated = finalLineAmounts.reduce((acc, la) => {
    acc.subtotal += la.subtotal;
    acc.discount += la.discount;
    acc.tax += la.tax;
    acc.total += la.total;
    return acc;
  }, { subtotal: 0n, discount: 0n, tax: 0n, total: 0n });

  // Sanity checks
  const recomputed = aggregated.subtotal - aggregated.discount + aggregated.tax;
  if (recomputed !== aggregated.total) {
    // This indicates rounding/distribution mismatch - surface as a business rule violation
    throw { code: ErrorCode.BUSINESS_RULE_VIOLATION, message: 'Rounding distribution mismatch', detail: { recomputed, aggregated } };
  }

  return { subtotal: aggregated.subtotal, tax: aggregated.tax, discount: aggregated.discount, total: aggregated.total };
}

// Notes:
// - All monetary arithmetic uses BigInt. Minor units are integers (10^precision). Quantities are scaled by QUANTITY_SCALE to support decimals.
// - Percentages are expressed in PPM (parts-per-million) to avoid floating math: 20% -> 200_000.
// - divRound implements configurable rounding (HALF_EVEN, HALF_UP, UP, DOWN) and is used whenever fractional minor-units would occur.
// - For FINAL_TOTAL rounding we provide a deterministic redistribution of any delta to preserve total consistency; the distribution strategy is proportional by subtotal and attaches leftover to largest subtotal line.
// - The code favors clarity for review; micro-optimizations (avoiding some BigInt ops) can be applied for extreme performance targets. Complexity is O(n) in number of items.

// If you want, I can paste the unrolled, fully-annotated line-by-line implementation used in unit tests (with exact BigInt values in sample cases) or a Java/Go variant using 64-bit ints where BigInt isn't available.

// Revised helpers and tests requested

// ComputationError class
export class ComputationError extends Error {
  code: ErrorCode;
  details?: any;
  constructor(code: ErrorCode, message: string, details?: any) {
    super(message);
    this.name = 'ComputationError';
    this.code = code;
    this.details = details;
    // Maintains proper stack trace in V8
    if ((Error as any).captureStackTrace) (Error as any).captureStackTrace(this, ComputationError);
  }
}

// Overflow guard constant (magnitude in minor units); tuneable per deployment
export const DEFAULT_MAX_MAGNITUDE: bigint = 10n ** 24n; // e.g. 1e24 minor-units (~1e22 major units for 2-decimal currencies)

// New parseDecimalToScaledBigInt
// - input: number|string (accepts leading ".5" as "0.5")
// - precision: number of fractional digits to preserve (e.g. currency.precision)
// - roundingMode: rounding to apply when input has more fractional digits than precision
// - maxMagnitude (optional): throw OVERFLOW if absolute scaled value > maxMagnitude
export function parseDecimalToScaledBigInt(
  input: number | string,
  precision: number,
  roundingMode: RoundingMode,
  maxMagnitude: bigint = DEFAULT_MAX_MAGNITUDE
): bigint {
  // Normalize to string
  if (typeof input === 'number') input = String(input);
  if (typeof input !== 'string') throw new ComputationError(ErrorCode.PARSE_ERROR, 'Unsupported numeric input type');
  const s = input.trim();
  if (s === '') throw new ComputationError(ErrorCode.PARSE_ERROR, 'Empty numeric string');
  if (s.includes(',')) throw new ComputationError(ErrorCode.PARSE_ERROR, 'Thousands separators not allowed');

  // Handle optional sign
  const neg = s.startsWith('-');
  const unsigned = neg ? s.slice(1) : s;

  // Split integer/frac; accept leading ".5" -> intPart = '0'
  const parts = unsigned.split('.');
  let intPart = parts[0] === '' ? '0' : parts[0];
  const fracPart = parts[1] ?? '';

  if (!/^[0-9]+$/.test(intPart)) throw new ComputationError(ErrorCode.PARSE_ERROR, 'Invalid integer part');
  if (fracPart !== '' && !/^[0-9]+$/.test(fracPart)) throw new ComputationError(ErrorCode.PARSE_ERROR, 'Invalid fraction part');

  // scaleFactor = 10^precision
  const scaleFactor = 10n ** BigInt(precision);

  // Prepare fraction digits (truncate to precision, but determine if we need to round)
  const fracNeeded = precision;
  const fracTrunc = fracPart.slice(0, fracNeeded).padEnd(fracNeeded, '0'); // string of length == precision
  const nextDigit = fracPart.length > fracNeeded ? fracPart.charAt(fracNeeded) : null;
  const tailAfterNext = fracPart.length > fracNeeded + 1 ? fracPart.slice(fracNeeded + 1) : '';

  // Build base scaled value (without rounding)
  const absInt = BigInt(intPart);
  const baseScaled = absInt * scaleFactor + BigInt(fracTrunc || '0');

  // Decide rounding
  let scaled = baseScaled;
  if (nextDigit !== null) {
    // There are extra digits => potentially round
    const anyFollowingNonZero = tailAfterNext.length > 0 && /[1-9]/.test(tailAfterNext);
    const nextDigitVal = Number(nextDigit);
    let shouldRoundUp = false;
    switch (roundingMode) {
      case 'UP': shouldRoundUp = (nextDigitVal > 0) || anyFollowingNonZero; break;
      case 'DOWN': shouldRoundUp = false; break;
      case 'HALF_UP': shouldRoundUp = (nextDigitVal >= 5); break;
      case 'HALF_EVEN': {
        if (nextDigitVal > 5) shouldRoundUp = true;
        else if (nextDigitVal < 5) shouldRoundUp = false;
        else {
          // nextDigitVal == 5
          if (anyFollowingNonZero) shouldRoundUp = true;
          else {
            // tie: round to even based on current least-significant digit of scaled
            shouldRoundUp = (baseScaled % 2n !== 0n);
          }
        }
        break;
      }
      default: shouldRoundUp = false;
    }
    if (shouldRoundUp) scaled = baseScaled + 1n;
  }

  const finalScaled = neg ? -scaled : scaled;

  // Overflow guard
  if (finalScaled > maxMagnitude || finalScaled < -maxMagnitude) {
    throw new ComputationError(ErrorCode.OVERFLOW, 'Numeric magnitude exceeds allowed bounds', { value: finalScaled.toString() });
  }

  return finalScaled;
}

// parsePercentToPpm: percent -> parts-per-million (ppm)
// We model ppm where 1% == 10_000 ppm, so precision == 4
export function parsePercentToPpm(input: number | string, roundingMode: RoundingMode): bigint {
  return parseDecimalToScaledBigInt(input, 4, roundingMode); // 20 -> 200_000
}

// parsePriceToMinorUnits: price in major units -> minor units (e.g. USD 12.34 -> 1234)
export function parsePriceToMinorUnits(
  input: number | string,
  currency: CurrencyConfig,
  roundingMode: RoundingMode,
  maxMagnitude: bigint = DEFAULT_MAX_MAGNITUDE
): bigint {
  return parseDecimalToScaledBigInt(input, currency.precision, roundingMode, maxMagnitude);
}

// --- Updated snippets showing propagation into applyDiscountsAndTaxes / distributeRounding ---
function applyDiscountsAndTaxes(
  items: LineItem[],
  opts: CalculationOptions
) {
  const results = [] as { id: string; subtotal: bigint; discount: bigint; tax: bigint; total: bigint }[];
  for (const it of items) {
    const qtyScaled = parseDecimalToScaledBigInt(it.quantity, 6, opts.roundingMode); // QUANTITY_SCALE precision = 6
    const unitPriceMinor = parsePriceToMinorUnits(it.unitPrice, opts.currency, opts.roundingMode);
    const rawSubtotalNumerator = qtyScaled * unitPriceMinor;
    const subtotal = divRound(rawSubtotalNumerator, 1_000_000n /* QUANTITY_SCALE */, opts.roundingMode);

    const discountPctPpm = it.discountPct ? parsePercentToPpm(it.discountPct, opts.roundingMode) : 0n;
    let discount = 0n;
    if (discountPctPpm !== 0n) {
      const discountNumerator = subtotal * discountPctPpm;
      discount = divRound(discountNumerator, PERCENT_PPM, opts.roundingMode);
    }

    const taxPctPpm = it.taxRatePct ? parsePercentToPpm(it.taxRatePct, opts.roundingMode) : 0n;
    let priceAfterDiscount = opts.applyDiscountBeforeTax ? (subtotal - discount) : subtotal;
    let tax = 0n;
    if (taxPctPpm !== 0n) {
      if (opts.pricesIncludeTax) {
        const denom = PERCENT_PPM + taxPctPpm;
        const taxNumerator = priceAfterDiscount * taxPctPpm;
        tax = divRound(taxNumerator, denom, opts.roundingMode);
      } else {
        const taxNumerator = priceAfterDiscount * taxPctPpm;
        tax = divRound(taxNumerator, PERCENT_PPM, opts.roundingMode);
      }
    }

    const total = priceAfterDiscount + tax;
    results.push({ id: it.id, subtotal, discount, tax, total });
  }
  return { lineAmounts: results };
}

function distributeRounding(lineAmounts: { id: string; subtotal: bigint; discount: bigint; tax: bigint; total: bigint }[], opts: CalculationOptions) {
  if (opts.roundingStrategy === 'PER_LINE') return lineAmounts;
  // ... same logic as before but use stable sort by id when needed
  const aggregated = lineAmounts.reduce((acc, la) => { acc.subtotal += la.subtotal; acc.discount += la.discount; acc.tax += la.tax; acc.total += la.total; return acc; }, { subtotal: 0n, discount: 0n, tax: 0n, total: 0n });
  const recomputedTotal = aggregated.subtotal - aggregated.discount + aggregated.tax;
  const delta = recomputedTotal - aggregated.total;
  if (delta === 0n) return lineAmounts;

  // Deterministic distribution: sort stable by id
  const sorted = [...lineAmounts].sort((a,b) => a.id.localeCompare(b.id));
  const totalSubtotal = aggregated.subtotal;
  let remainder = delta;
  let adjusted = sorted.map(la => {
    const share = totalSubtotal === 0n ? 0n : (delta * la.subtotal) / totalSubtotal;
    remainder -= share;
    return { ...la, total: la.total + share };
  });

  if (remainder !== 0n) {
    // If totalSubtotal == 0, attach to first item deterministically; ensure non-empty
    if (adjusted.length === 0) throw new ComputationError(ErrorCode.BUSINESS_RULE_VIOLATION, 'No line items to distribute rounding remainder');
    adjusted[0].total += remainder;
  }
  // return in original input order by mapping ids back
  const byId = new Map(adjusted.map(a => [a.id, a]));
  return lineAmounts.map(l => byId.get(l.id)!);
}

