// Constants block
export const QUANTITY_PRECISION = 6; // fractional digits for quantity
export const QUANTITY_SCALE = 10n ** BigInt(QUANTITY_PRECISION); // 1_000_000n
export const PERCENT_PPM = 1_000_000n; // denominator for ppm arithmetic
export const DEFAULT_MAX_MAGNITUDE: bigint = 10n ** 24n; // safe magnitude bound for minor-units

// --- Revised applyDiscountsAndTaxes with pre/post-multiplication overflow checks ---
function applyDiscountsAndTaxes(
  items: LineItem[],
  opts: CalculationOptions
) {
  const results: { id: string; subtotal: bigint; discount: bigint; tax: bigint; total: bigint }[] = [];
  for (const it of items) {
    // parse quantity & unit price using centralized helpers and opts.roundingMode
    const qtyScaled = parseDecimalToScaledBigInt(it.quantity, QUANTITY_PRECISION, opts.roundingMode, DEFAULT_MAX_MAGNITUDE);
    const unitPriceMinor = parsePriceToMinorUnits(it.unitPrice, opts.currency, opts.roundingMode, DEFAULT_MAX_MAGNITUDE);

    // Overflow guard BEFORE multiplication: ensure qtyScaled * unitPriceMinor won't exceed max
    const abs = (x: bigint) => (x < 0n ? -x : x);
    const maxOperand = abs(unitPriceMinor) > 0n ? abs(unitPriceMinor) : 1n; // avoid division by zero
    if (abs(qtyScaled) > DEFAULT_MAX_MAGNITUDE / maxOperand) {
      throw new ComputationError(ErrorCode.OVERFLOW, 'Potential overflow in qty * unitPrice multiplication', { qtyScaled: qtyScaled.toString(), unitPriceMinor: unitPriceMinor.toString() });
    }

    // perform multiplication
    const rawSubtotalNumerator = qtyScaled * unitPriceMinor;

    // Post-multiplication check as additional safety
    if (abs(rawSubtotalNumerator) > DEFAULT_MAX_MAGNITUDE) {
      throw new ComputationError(ErrorCode.OVERFLOW, 'Multiplication produced value exceeding safe magnitude', { value: rawSubtotalNumerator.toString() });
    }

    // Convert scaled-quantity * unitPriceMinor -> minor-units subtotal with rounding
    const subtotal = divRound(rawSubtotalNumerator, QUANTITY_SCALE, opts.roundingMode);

    // Discounts (percentage)
    const discountPctPpm = it.discountPct ? parsePercentToPpm(it.discountPct, opts.roundingMode) : 0n;
    let discount = 0n;
    if (discountPctPpm !== 0n) {
      const discountNumerator = subtotal * discountPctPpm;
      // check intermediate magnitude
      if (abs(discountNumerator) > DEFAULT_MAX_MAGNITUDE * PERCENT_PPM) {
        throw new ComputationError(ErrorCode.OVERFLOW, 'Intermediate discount computation overflow', { value: discountNumerator.toString() });
      }
      discount = divRound(discountNumerator, PERCENT_PPM, opts.roundingMode);
    }

    // Taxes
    const taxPctPpm = it.taxRatePct ? parsePercentToPpm(it.taxRatePct, opts.roundingMode) : 0n;
    let priceAfterDiscount = opts.applyDiscountBeforeTax ? (subtotal - discount) : subtotal;
    let tax = 0n;
    if (taxPctPpm !== 0n) {
      if (opts.pricesIncludeTax) {
        const denom = PERCENT_PPM + taxPctPpm;
        const taxNumerator = priceAfterDiscount * taxPctPpm;
        if (abs(taxNumerator) > DEFAULT_MAX_MAGNITUDE * denom) {
          throw new ComputationError(ErrorCode.OVERFLOW, 'Intermediate tax computation overflow', { value: taxNumerator.toString() });
        }
        tax = divRound(taxNumerator, denom, opts.roundingMode);
      } else {
        const taxNumerator = priceAfterDiscount * taxPctPpm;
        if (abs(taxNumerator) > DEFAULT_MAX_MAGNITUDE * PERCENT_PPM) {
          throw new ComputationError(ErrorCode.OVERFLOW, 'Intermediate tax computation overflow', { value: taxNumerator.toString() });
        }
        tax = divRound(taxNumerator, PERCENT_PPM, opts.roundingMode);
      }
    }

    const total = priceAfterDiscount + tax;
    results.push({ id: it.id, subtotal, discount, tax, total });
  }
  return { lineAmounts: results };
}

// --- Updated distributeRounding: empty-array safety and deterministic stable-sort tie-breaker ---
function distributeRounding(lineAmounts: { id: string; subtotal: bigint; discount: bigint; tax: bigint; total: bigint }[], opts: CalculationOptions) {
  if (opts.roundingStrategy === 'PER_LINE') return lineAmounts;
  if (!lineAmounts || lineAmounts.length === 0) return []; // empty-invoice handled gracefully by caller (calculateRevenue returns zeros)

  const aggregated = lineAmounts.reduce((acc, la) => {
    acc.subtotal += la.subtotal; acc.discount += la.discount; acc.tax += la.tax; acc.total += la.total; return acc;
  }, { subtotal: 0n, discount: 0n, tax: 0n, total: 0n });

  const recomputedTotal = aggregated.subtotal - aggregated.discount + aggregated.tax;
  const delta = recomputedTotal - aggregated.total;
  if (delta === 0n) return lineAmounts;

  // Deterministic distribution: stable sort by id
  const sorted = [...lineAmounts].sort((a, b) => a.id.localeCompare(b.id));
  const totalSubtotal = aggregated.subtotal;
  let remainder = delta;
  const adjusted = sorted.map(la => {
    const share = totalSubtotal === 0n ? 0n : (delta * la.subtotal) / totalSubtotal;
    remainder -= share;
    return { ...la, total: la.total + share };
  });

  if (remainder !== 0n) {
    // attach remainder deterministically to first element after stable sort
    adjusted[0].total += remainder;
  }

  // Map back to original input order
  const byId = new Map(adjusted.map(a => [a.id, a]));
  return lineAmounts.map(l => byId.get(l.id)!);
}

