    expect(parsePercentToPpm('0.5', 'HALF_EVEN')).toBe(5000n);
  });

  test('price rounding: "12.345" -> 1234 HALF_EVEN, 1235 HALF_UP', () => {
    expect(parsePriceToMinorUnits('12.345', { code: 'USD', precision: 2 }, 'HALF_EVEN')).toBe(1234n);
    expect(parsePriceToMinorUnits('12.345', { code: 'USD', precision: 2 }, 'HALF_UP')).toBe(1235n);
  });

  test('multiplication overflow: very large qty * very large price throws OVERFLOW', () => {
    const hugeQty = '1' + '0'.repeat(20); // extremely large quantity string
    const hugePrice = '1' + '0'.repeat(20); // extremely large price string
    const item = { id: 'x', quantity: hugeQty, unitPrice: hugePrice } as LineItem;
    const opts: CalculationOptions = { currency: { code: 'USD', precision: 2 }, roundingStrategy: 'PER_LINE', roundingMode: 'HALF_EVEN', applyDiscountBeforeTax: true, pricesIncludeTax: false };
    expect(() => applyDiscountsAndTaxes([item], opts)).toThrowError(ComputationError);
    try { applyDiscountsAndTaxes([item], opts); } catch (e) { expect((e as ComputationError).code).toBe(ErrorCode.OVERFLOW); }
  });

  test('empty-invoice returns zeroed computation result', () => {
    const res = calculateRevenue([], { currency: { code: 'USD', precision: 2 }, roundingStrategy: 'PER_LINE', roundingMode: 'HALF_EVEN', applyDiscountBeforeTax: true, pricesIncludeTax: false });
    expect(res).toEqual({ subtotal: 0n, tax: 0n, discount: 0n, total: 0n });
  });

  test('FINAL_TOTAL mapping: per-line rounding differs and redistributes deterministically', () => {
    const items: LineItem[] = [
      { id: 'a', quantity: '0.333333', unitPrice: '1.00' },
      { id: 'b', quantity: '0.333333', unitPrice: '1.00' },
      { id: 'c', quantity: '0.333334', unitPrice: '1.00' }
    ];
    const opts: CalculationOptions = { currency: { code: 'USD', precision: 2 }, roundingStrategy: 'FINAL_TOTAL', roundingMode: 'HALF_EVEN', applyDiscountBeforeTax: true, pricesIncludeTax: false };
    const result = calculateRevenue(items, opts);
    // total should equal sum(subtotals)-discount+tax, deterministic and mapped back to input order; assert non-negative and consistent
    expect(result.total).toBe(result.subtotal - result.discount + result.tax);
  });

  test('refund path: negative qty/price allowed when isRefund=true', () => {
    const items: LineItem[] = [{ id: 'r1', quantity: '-1', unitPrice: '-10.00' }];
    const opts: CalculationOptions = { currency: { code: 'USD', precision: 2 }, roundingStrategy: 'PER_LINE', roundingMode: 'HALF_EVEN', applyDiscountBeforeTax: true, pricesIncludeTax: false, isRefund: true };
    const res = calculateRevenue(items, opts);
    // negative total allowed in refund flow
    expect(res.total).toBeLessThanOrEqual(0n);
  });
});

